interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (english: string) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);
const STORAGE_KEY = "cyrech-language";

const detectLanguage = (): Language => {
  const saved = localStorage.getItem(STORAGE_KEY);
  if (saved && languages.includes(saved as Language)) return saved as Language;
  for (const preferred of navigator.languages ?? [navigator.language]) {
    const base = preferred.toLowerCase().split("-")[0];
    if (languages.includes(base as Language)) return base as Language;
  }
  return "en";
};

export const LanguageProvider = ({ children }: { children: ReactNode }) => {
  const [language, setLanguageState] = useState<Language>(detectLanguage);
  const setLanguage = useCallback((next: Language) => {
    localStorage.setItem(STORAGE_KEY, next);
    setLanguageState(next);
  }, []);
  const t = useCallback(
    (english: string) => copy[language][english] ?? supplementalCopy[english]?.[language] ?? english,
    [language],
  );

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const value = useMemo(() => ({ language, setLanguage, t }), [language, setLanguage, t]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used within LanguageProvider");
  return context;
};
